// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.emotionimport com.roshan.persona.voice.capture.AudioCapturePipeline/** * NOUS — User Emotion data model (§16 Speech Emotion Recognition). * * Represents the emotional state detected from the user's voice — distinct * from NOUS's own emotion (which lives in [com.roshan.persona.voice.tts.Emotion]). * User emotion is *input* to the Brain; NOUS's emotion is *output* (how NOUS * responds). * * ## The 7 user emotions (§16) * * Per the v2 strategy doc, the WavLM SER model outputs these classes: * * | Emotion    | Use case                                          | * |------------|---------------------------------------------------| * | NEUTRAL    | Default — user speaking normally                  | * | HAPPY      | User laughing / cheerful — NOUS matches tone      | * | SAD        | User sharing bad news — NOUS goes CALM/APOLOGETIC | * | ANGRY      | User frustrated — NOUS stays CALM to de-escalate  | * | FEARFUL    | User scared — NOUS goes CALM, reassuring          | * | SURPRISED  | User shocked — NOUS acknowledges surprise         | * | DISGUSTED  | User repulsed — NOUS acknowledges + redirects     | * * ## Brain integration (§16 Brain Integration) * * The Brain receives `[USER_EMOTION=ANGRY]` in its context and adjusts * both the response content and the TTS emotion: * * ``` * User: "Lights on!" (angry) *   ↓ * STT: "Lights on" * SER: ANGRY (confidence 0.82) *   ↓ * Brain context: [USER_EMOTION=ANGRY] *   ↓ * Brain response: "Of course. Turning on the lights now." (conciliatory) *   ↓ * TTS emotion: CALM (NOT ANGRY — NOUS stays calm to de-escalate) * ``` * * ## Testability * * [UserEmotion] is a plain data class. [UserEmotionType] is an enum with a * `fromConfidenceMap` factory that the recognizer uses. All values are * plain floats — no Android dependencies — so tests can verify the data * model directly. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§16 Speech Emotion Recognition — v2 Fix #1</a> *//** * One emotion detection result. * * @param primary     the highest-scoring emotion. * @param confidence  confidence in the primary emotion (0.0–1.0). * @param allScores   all emotions with their scores (for debugging + UI). * @param source      which detector produced this result (WavLM / heuristic). */data class UserEmotion(    val primary: UserEmotionType,    val confidence: Float,    val allScores: Map<UserEmotionType, Float>,    val source: EmotionDetectionSource = EmotionDetectionSource.WAVLM,) {    init {        require(confidence in 0f..1f) { "confidence must be in [0,1], got $confidence" }        require(allScores.isNotEmpty()) { "allScores must not be empty" }        require(allScores.values.all { it in 0f..1f }) {            "all emotion scores must be in [0,1]"        }        require(primary in allScores) {            "primary emotion $primary not present in allScores"        }    }    companion object {        /** Minimum confidence for the Brain to act on the detected emotion. */        const val RELIABLE_CONFIDENCE = 0.6f        /** Sentinel for "no audio / detection failed" — caller checks isReliable. */        val UNKNOWN = UserEmotion(            primary = UserEmotionType.NEUTRAL,            confidence = 0f,            allScores = mapOf(UserEmotionType.NEUTRAL to 0f),            source = EmotionDetectionSource.UNKNOWN,        )        /**         * Build a [UserEmotion] from a raw confidence map by picking the         * highest-scoring emotion as primary.         */        fun fromScores(            scores: Map<UserEmotionType, Float>,            source: EmotionDetectionSource = EmotionDetectionSource.WAVLM,        ): UserEmotion {            require(scores.isNotEmpty()) { "scores must not be empty" }            // maxByOrNull returns Map.Entry<UserEmotionType, Float>? — destructured            // to .key (UserEmotionType) and .value (Float). When the map is            // non-empty (guaranteed by the require above), the result is non-null.            val best = scores.maxByOrNull { it.value }            return if (best != null) {                UserEmotion(                    primary = best.key,                    confidence = best.value,                    allScores = scores,                    source = source,                )            } else {                // Defensive fallback — require() above guarantees non-empty,                // but Kotlin's smart-cast can't prove it across the ?: chain.                UserEmotion(                    primary = UserEmotionType.NEUTRAL,                    confidence = 0f,                    allScores = scores,                    source = source,                )            }        }    }    /**     * True if the detection is reliable enough to act on.     *     * Below [RELIABLE_CONFIDENCE], the Brain should ignore the emotion and     * treat the user as NEUTRAL — acting on a 0.4-confidence "ANGRY" would     * cause NOUS to over-apologize on every neutral utterance.     */    val isReliable: Boolean        get() = source != EmotionDetectionSource.UNKNOWN &&            confidence >= RELIABLE_CONFIDENCE    /**     * Map the user's emotion to a NOUS response emotion (per §16 Brain Integration).     *     * NOUS doesn't mirror the user — it responds with an appropriate emotion:     *  - User ANGRY → NOUS CALM (de-escalate)     *  - User SAD → NOUS CALM (reassure)     *  - User FEARFUL → NOUS CALM (reassure)     *  - User HAPPY → NOUS HAPPY (match)     *  - User SURPRISED → NOUS NEUTRAL (acknowledge)     *  - User DISGUSTED → NOUS NEUTRAL (acknowledge + redirect)     *  - User NEUTRAL → NOUS NEUTRAL     */    fun toNousResponseEmotion(): com.roshan.persona.voice.tts.Emotion = when (primary) {        UserEmotionType.NEUTRAL -> com.roshan.persona.voice.tts.Emotion.NEUTRAL        UserEmotionType.HAPPY -> com.roshan.persona.voice.tts.Emotion.HAPPY        UserEmotionType.SAD -> com.roshan.persona.voice.tts.Emotion.CALM        UserEmotionType.ANGRY -> com.roshan.persona.voice.tts.Emotion.CALM  // de-escalate        UserEmotionType.FEARFUL -> com.roshan.persona.voice.tts.Emotion.CALM        UserEmotionType.SURPRISED -> com.roshan.persona.voice.tts.Emotion.NEUTRAL        UserEmotionType.DISGUSTED -> com.roshan.persona.voice.tts.Emotion.NEUTRAL    }}// ──────────────────────────────────────────────────────────────────────────/** The 7 user emotion classes output by the WavLM SER model (§16). */enum class UserEmotionType {    NEUTRAL,    HAPPY,    SAD,    ANGRY,    FEARFUL,    SURPRISED,    DISGUSTED,}// ──────────────────────────────────────────────────────────────────────────/** Which detector produced an emotion result. */enum class EmotionDetectionSource {    /** WavLM/HuBERT SER model (ONNX, 45 MB) — primary, ~85 % accuracy. */    WAVLM,    /** Heuristic fallback (pitch + energy + rate) — ~55 % accuracy. */    HEURISTIC,    /** Detection failed (audio too short, model unavailable, etc.). */    UNKNOWN,}// ──────────────────────────────────────────────────────────────────────────/** * Configuration for the speech emotion recognizer. * * @param wavlmModelPath     path to `wavlm_ser.onnx` (45 MB). Null disables *                            WavLM, falls back to heuristic. * @param minAudioSeconds    minimum audio length for reliable detection. *                            Default 1 s — shorter clips have too little signal. * @param reliableThreshold  minimum confidence for [UserEmotion.isReliable]. *                            Default 0.6 — below this, the Brain ignores emotion. * @param parallelToStt      if true (default), the recognizer runs on its own *                            dispatcher so it doesn't block STT. Per §16, SER *                            runs in parallel with STT and doesn't add latency. */data class SerConfig(    val wavlmModelPath: String? = null,    val minAudioSeconds: Int = DEFAULT_MIN_AUDIO_SECONDS,    val reliableThreshold: Float = UserEmotion.RELIABLE_CONFIDENCE,    val parallelToStt: Boolean = true,) {    init {        require(minAudioSeconds in 1..30) { "minAudioSeconds must be 1..30" }        require(reliableThreshold in 0f..1f) { "reliableThreshold must be in [0,1]" }    }    companion object {        const val DEFAULT_MIN_AUDIO_SECONDS = 1        const val MIN_AUDIO_SAMPLES = AudioCapturePipeline.SAMPLE_RATE  // 1 second    }}